"""Decision guide for brands considering GEO."""


def brand_guide(contact):
    return f'''<div class="brand-guide">
    <header class="guide-cover wrap"><div><h1>Зачем бренду GEO</h1>
    <p class="short-answer">Чтобы покупатель увидел ваше предложение, когда выбирает компанию в нейросети. К моменту перехода на сайт у него уже может сложиться мнение о вас и ваших конкурентах.</p>
    <div class="actions"><a class="btn primary" href="{contact}" data-open-brief>Обсудить мой бренд ↗</a><a class="edition-link" href="#investment">Оценить задачу ↓</a></div></div>
    <figure class="choice-figure"><figcaption>Что формирует выбор покупателя</figcaption>
    <ol><li><span>Круг компаний</span><strong>Кого покупатель увидит</strong></li>
    <li><span>Сравнение</span><strong>Что узнает о вашем продукте</strong></li>
    <li><span>Следующий шаг</span><strong>На какой сайт перейдёт</strong></li></ol></figure></header>
    <section class="wrap guide-opportunity" id="investment"><h2>Где у бизнеса появляется возможность для роста</h2>
    <div><p>Спрос может уже существовать, даже если в нём не звучит название вашей компании. Покупатель описывает потребность своими словами. Нейросеть сужает выбор и объясняет, какие варианты подходят под его условия.</p>
    <p>Вопрос для бизнеса в том, есть ли вы в этом выборе. Если бренд редко встречается, стоит искать темы, в которых вас обходят. Если компания уже заметна, важнее проверить, верно ли покупателю объясняют преимущества и условия.</p></div></section>
    <section class="wrap guide-signals" id="visibility"><header><h2>Три стороны видимости</h2>
    <p>Один показатель не расскажет, какое впечатление получит покупатель. Посмотрите на ответ с трёх сторон.</p></header>
    <dl><div><dt>Присутствие</dt><dd>Узнаёт ли покупатель о вас, когда ищет решение без названия бренда? Здесь важны темы, по которым компания действительно хочет получать обращения.</dd></div>
    <div><dt>Репутация</dt><dd>Какие качества нейросеть приписывает продукту? Даже знакомый бренд может потерять клиента, если в ответе остались устаревшие условия или исчезло важное преимущество.</dd></div>
    <div><dt>Источник</dt><dd>Где покупатель продолжит знакомство? В ответе может стоять ссылка на ваш сайт, на публикацию о вас или на площадку, которая предлагает несколько компаний сразу.</dd></div></dl></section>
    <section class="wrap guide-decision" id="outcome"><header id="demand"><h2>Как выбрать первое направление</h2>
    <p>Начните с той части бизнеса, где выбор клиента ещё открыт, а результат важен для продаж.</p></header>
    <ol><li><strong>Выберите приоритет для бизнеса</strong><p>По какому продукту или услуге вам нужны новые клиенты? На каких рынках вы можете выполнить заказ? Границы задачи пригодятся и для оценки результата.</p></li>
    <li><strong>Посмотрите, с кем вас сравнивают</strong><p>Уточните у отдела продаж, какие альтернативы называют покупатели и что им важно при выборе. Так будет понятнее, заслуживают ли внимания темы, по которым в ответах появляются конкуренты.</p></li>
    <li><strong>Определите признак результата</strong><p>Для малоизвестного бренда это может быть появление в нужных сравнениях. Для известного важнее точность описания и переход на официальную страницу. Обращения и продажи оценивают по данным самого бизнеса.</p></li></ol></section>
    <aside class="wrap guide-evidence"><div><h2>Как это выглядит в работе</h2>
    <p>В проекте модного бренда мы могли сопоставить изменения в ответах с переходами на два сайта. В проекте WINLINE задача была другой: определить, по каким темам стоит доработать официальный сайт.</p></div>
    <div><a href="{{PRE}}cases/fashion/">История продвижения бренда <span>↗</span></a><a href="{{PRE}}cases/winline/">Аудит WINLINE <span>↗</span></a></div></aside></div>'''
